return {api_version=1,id="EX1_611",name="Freezing Trap",text="<b>Secret:</b> When an enemy minion attacks, return it to its owner's hand. It costs (2) more.",set="EXPERT1",type="spell",class="hunter",rarity="common",spell_school="frost",cost=2,keywords={"secret"},triggers={{event="attack",timing="before",active_zones={"secret"},condition=function(ctx,self,e)return ctx:controller(e.attacker)~=ctx:controller(self)and ctx:entity(e.attacker).type=="minion"end,effect=function(ctx,self,e)local owner=ctx:entity(e.attacker).owner;ctx:reveal_secret(self);cardlib.effects.move_to_hand(ctx, owner,e.attacker);cardlib.effects.modify(ctx, e.attacker,{stat="cost",operation="add",value=2})end}}}
